import{_ as e,o as a,c as s,ag as t}from"./chunks/framework.DXGyWiRo.js";const k=JSON.parse('{"title":"Authentication","description":"Configure authentication modes for DOAI Proxy using the AUTH_MODE environment variable","frontmatter":{"title":"Authentication","description":"Configure authentication modes for DOAI Proxy using the AUTH_MODE environment variable"},"headers":[],"relativePath":"guides/authentication.md","filePath":"guides/authentication.md"}'),n={name:"guides/authentication.md"};function o(l,i,r,h,d,p){return a(),s("div",null,[...i[0]||(i[0]=[t('<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>DOAI Proxy supports four authentication modes configured via <code>AUTH_MODE</code> environment variable. All auth checks use timing-safe comparison (<code>crypto.timingSafeEqual</code>) to prevent timing attacks.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><h3 id="required-recommended-for-production" tabindex="-1"><code>required</code> (recommended for production) <a class="header-anchor" href="#required-recommended-for-production" aria-label="Permalink to &quot;`required` (recommended for production)&quot;">​</a></h3><p><code>PROXY_API_KEY</code> must be set. All <code>/v1/*</code> requests must carry <code>Authorization: Bearer &lt;key&gt;</code>. Requests without a valid key receive <code>401 Unauthorized</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AUTH_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">required</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PROXY_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_secret_key_here</span></span></code></pre></div><h3 id="optional-good-for-development" tabindex="-1"><code>optional</code> (good for development) <a class="header-anchor" href="#optional-good-for-development" aria-label="Permalink to &quot;`optional` (good for development)&quot;">​</a></h3><p>Auth is enforced only if <code>PROXY_API_KEY</code> is set. If no key is configured, all requests are allowed. In production, a warning is logged if no key is set.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AUTH_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">optional</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PROXY_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_secret_key_here</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # optional</span></span></code></pre></div><h3 id="disabled" tabindex="-1"><code>disabled</code> <a class="header-anchor" href="#disabled" aria-label="Permalink to &quot;`disabled`&quot;">​</a></h3><p>No authentication. All requests are allowed. A loud warning is emitted on startup. Use only in isolated environments.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AUTH_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">disabled</span></span></code></pre></div><h3 id="external" tabindex="-1"><code>external</code> <a class="header-anchor" href="#external" aria-label="Permalink to &quot;`external`&quot;">​</a></h3><p>Auth is handled by a downstream gateway (Kubernetes service mesh, API gateway, etc.). Optionally checks for the presence of a custom header via <code>EXTERNAL_AUTH_HEADER</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AUTH_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">external</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EXTERNAL_AUTH_HEADER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-API-Gateway-Auth</span></span></code></pre></div><h2 id="client-configuration" tabindex="-1">Client Configuration <a class="header-anchor" href="#client-configuration" aria-label="Permalink to &quot;Client Configuration&quot;">​</a></h2><p>When auth is enabled, configure your client to send the API key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># With curl</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8000/v1/chat/completions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer your_proxy_api_key&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;model&quot;: &quot;...&quot;, &quot;messages&quot;: [...]}&#39;</span></span></code></pre></div><p>For OpenCode, add the API key to your configuration.</p><h2 id="default-behavior" tabindex="-1">Default Behavior <a class="header-anchor" href="#default-behavior" aria-label="Permalink to &quot;Default Behavior&quot;">​</a></h2><p>When <code>AUTH_MODE</code> is not explicitly set:</p><ul><li><strong>Production</strong> (<code>NODE_ENV=production</code>): Defaults to <code>required</code></li><li><strong>Development</strong> (<code>NODE_ENV=development</code>): Defaults to <code>optional</code></li></ul><h2 id="security-considerations" tabindex="-1">Security Considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to &quot;Security Considerations&quot;">​</a></h2><ul><li>Use strong, randomly generated keys for <code>PROXY_API_KEY</code></li><li>Never commit API keys to version control</li><li>Use HTTPS in production to protect keys in transit</li><li>Consider adding rate limiting for production deployments (see <a href="/guides/production">Production</a>)</li></ul>',24)])])}const u=e(n,[["render",o]]);export{k as __pageData,u as default};
